const collections=[{id:'kybalion',name:'THE KYBALION',line:'SEVEN PRINCIPLES. ONE INNER WORLD.',symbol:'GOLD / PHILOSOPHY',description:'Seven hermetic principles translated into geometric forms. A gold alchemical seal on a black hoodie, created as a study in the relationship between mind and matter.'},{id:'shadow',name:'SHADOW WORK',line:'MEET THE PARTS YOU HIDE.',symbol:'CHROME / INTROSPECTION',description:'A monochrome study of the inner work. Silver geometry and the words KNOW THYSELF invite a closer look at what sits beneath the surface.'},{id:'transmute',name:'AS ABOVE / SO BELOW',line:'CHANGE BEGINS WITHIN.',symbol:'OXIDE / TRANSFORMATION',description:'Oxide red on black. The paired triangles become a symbol of correspondence and transformation, connecting the inner world with the world outside.'}];
const products=document.querySelector('#products');function render(filter='all'){products.innerHTML=collections.filter(p=>filter==='all'||p.id===filter).map(p=>`<article class="product-card"><button data-detail="${p.id}" aria-label="Explore ${p.name}"><span class="tag">COLLECTION STUDY</span><img loading="lazy" src="/assets/${p.id}.svg" alt="Illustrative ${p.name} hoodie design"><span class="product-arrow">↗</span></button><div class="product-meta"><div><h3>${p.name}</h3><p>${p.line}</p></div><span>0${collections.indexOf(p)+1}</span></div></article>`).join('')};render();
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));render(b.dataset.filter)}));
const modal=document.querySelector('#detail'),content=document.querySelector('#detail-body');function open(html){content.innerHTML=html;modal.showModal()}document.querySelector('.close').onclick=()=>modal.close();modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});
products.addEventListener('click',e=>{const b=e.target.closest('[data-detail]');if(!b)return;const p=collections.find(x=>x.id===b.dataset.detail);open(`<div class="detail-grid"><img src="/assets/${p.id}.svg" alt="${p.name} illustrative concept"><div><span class="eyebrow">${p.symbol}</span><h2>${p.name}</h2><p>${p.description}</p><p>Design concept. This preview does not confirm a product SKU, price, edition size, stock or Printful availability. View the live Magento store for purchasable products.</p><a class="button" target="_blank" rel="noopener" href="https://magento.caisik.i234.me/">OPEN THE STORE ↗</a></div></div>`)});
document.querySelectorAll('[data-art]').forEach(b=>b.onclick=()=>{document.querySelector('#garment').src=`/assets/${b.dataset.art}.svg`;document.querySelector('#garment').alt=`Illustrative ${b.dataset.art} hoodie concept`;document.querySelectorAll('[data-art]').forEach(x=>x.classList.toggle('active',x===b))});
const principles=[['I','MENTALISM','It starts in the mind.','The first principle places mind at the centre of experience. Our interpretation: examine the story you tell yourself before you let it shape your world.'],['II','CORRESPONDENCE','Look within. Look around.','As above, so below. The collection interprets correspondence through mirrored triangles: an invitation to notice patterns across different scales of life.'],['III','VIBRATION','Nothing stands still.','Vibration describes a universe in motion. In this collection, the symbol becomes a reminder that your perspective can move too.'],['IV','POLARITY','Hold both sides.','Opposites become a way to consider a spectrum. Light and shadow, stillness and movement: the design asks what becomes visible when you hold both.'],['V','RHYTHM','Find your own rhythm.','The imagery of cycles and returning movement becomes a prompt to observe your habits, seasons and pace.'],['VI','CAUSE & EFFECT','Choose your next move.','Every action has consequences. Here the principle becomes a practical question: what are you setting in motion today?'],['VII','GENERATION','Make something real.','The historical principle of gender is interpreted here through creative and receptive qualities. It is a philosophical motif, not a biological or scientific claim.']];
document.querySelector('#principles').innerHTML=principles.map((p,i)=>`<button class="${i===0?'selected':''}" data-principle="${i}" aria-label="${p[1]}">${p[0]}</button>`).join('');document.querySelectorAll('[data-principle]').forEach(b=>b.onclick=()=>{const p=principles[+b.dataset.principle];document.querySelector('#principle-number').textContent=`${p[0]} / ${p[1]}`;document.querySelector('#principle-title').textContent=p[2];document.querySelector('#principle-body').textContent=p[3];document.querySelectorAll('[data-principle]').forEach(x=>x.classList.toggle('selected',x===b))});
const campaigns=['transmute','mentalism','correspondence','vibration','polarity','rhythm','cause-effect','generation','shadow-work','as-above','so-below','underground'];document.querySelector('#sticker-open').onclick=()=>open(`<span class="eyebrow">THE STREET SERIES / 12 PORTALS</span><h2>LEAVE A SIGN.</h2><p>Download vector QR artwork. Each code includes its campaign parameters and links to this private Site. Public access and final destination must be configured before physical printing.</p><div class="qr-grid">${campaigns.map((c,i)=>`<a href="/assets/qr-${c}.svg" download="caisik-${c}.svg"><b>${String(i+1).padStart(2,'0')} / ${c.toUpperCase()}</b><img src="/assets/qr-${c}.svg" alt="Download QR code for ${c}"><small>DOWNLOAD VECTOR SVG ↓</small></a>`).join('')}</div>`);
document.querySelector('#privacy-open').onclick=()=>open(`<span class="eyebrow">PROJECT STATUS / OCTOBER 2026</span><h2>TRANSPARENT BY DESIGN.</h2><p>This is a visual first phase of CAISIK Underground Alchemy. The garments are original illustrative collection studies, not a verified sales catalog.</p><p>Magento returned HTTP 200, but both public GraphQL catalog queries returned zero products. Links open the existing Magento store. Cart, checkout, payment, order sync and Printful fulfillment have not been integrated or tested here.</p><p>No analytics, cookies, email collection or browser storage is implemented by this page. QR URLs include campaign parameters; scans and sales are not measured. Google Fonts may make external requests. The Sites host and the external Magento store apply their own privacy practices.</p><p>The QR destinations currently use this owner-private Site. They are not ready for a public sticker campaign. This build does not access Synology or change production data.</p>`);
const path=location.pathname.split('/').filter(Boolean);if(path[0]==='q'){const slug=path[1];if(campaigns.includes(slug)){document.querySelector('#portal').hidden=false;document.querySelector('#portal-title').textContent=slug.replaceAll('-',' ').toUpperCase();document.title=`${slug.toUpperCase()} — CAISIK`;document.querySelector('main').setAttribute('inert','');document.querySelector('header').setAttribute('inert','')}}
